import { createStrictRuntimeProjectFilesClient, } from "../runtime/project-files-client.js";
import { getRuntimeProjectInstructions, getRuntimeProjectSkillCatalog, } from "../runtime/project-skill-catalog.js";
import { resolveRuntimeSkillSelectorSnapshotForAgent, } from "../runtime/skill-metadata.js";
import { assertResolvedSkillSelector, createNoneSkillSelectorSnapshot, } from "../../skill/selector.js";
import { buildInteractiveVeryfrontCloudRuntimeInstructions, resolveHostedRuntimeSkillLoaderToolName, } from "./cloud-runtime-system-messages.js";
import { isLoadSkillToolName } from "../platform-tool-names.js";
/**
 * Create broker-owned project steering. Refreshes show skills only when the
 * broker-validated effective tool selection includes `veryfront__load_skill`.
 */
export function createManagedBrokerProjectState(options) {
    if (!options.agentId || !options.authToken) {
        throw new TypeError("Managed broker project state requires fixed identity and authorization");
    }
    const projectId = options.projectId;
    const branchId = options.branchId;
    const authToken = options.authToken;
    const projectClient = createStrictRuntimeProjectFilesClient({
        apiUrl: new URL(options.apiUrl).toString(),
        fetch: options.fetch,
    });
    const builtinSkills = [...options.builtinSkills ?? []];
    let definition;
    const assertScope = (input) => {
        if (input.projectId !== projectId || input.branchId !== branchId) {
            throw new TypeError("Managed broker project state scope cannot change");
        }
    };
    const fileReader = (signal) => async (input) => {
        assertScope(input);
        if (input.authToken !== authToken || projectId === null) {
            throw new TypeError("Managed broker project authorization cannot change");
        }
        return await projectClient.getProjectFile({ ...input, signal });
    };
    const fileLister = (signal) => async (input) => {
        assertScope(input);
        if (input.authToken !== authToken || projectId === null) {
            throw new TypeError("Managed broker project authorization cannot change");
        }
        return await projectClient.getProjectFiles({ ...input, signal });
    };
    const load = async (signal) => {
        signal.throwIfAborted();
        if (projectId === null)
            return { instructions: "", skills: [] };
        const lookup = { projectId, branchId, authToken };
        const [instructionsResult, skillsResult] = await Promise.allSettled([
            getRuntimeProjectInstructions({ ...lookup, getProjectFile: fileReader(signal) }),
            getRuntimeProjectSkillCatalog({
                ...lookup,
                getProjectFile: fileReader(signal),
                getProjectFiles: fileLister(signal),
                builtinSkills,
                skillDocumentParserProvider: options.skillDocumentParserProvider,
            }),
        ]);
        if (instructionsResult.status === "rejected")
            throw instructionsResult.reason;
        if (skillsResult.status === "rejected")
            throw skillsResult.reason;
        signal.throwIfAborted();
        return { instructions: instructionsResult.value, skills: skillsResult.value };
    };
    const select = (agent, skills) => {
        if (agent.skills === false)
            return createNoneSkillSelectorSnapshot();
        const selected = resolveRuntimeSkillSelectorSnapshotForAgent({
            skills,
            agentId: agent.id,
            selector: agent.skills,
        });
        assertResolvedSkillSelector(selected);
        return selected;
    };
    return {
        async prepareProjectSteering(input) {
            assertScope(input);
            if (input.definition.id !== options.agentId) {
                throw new TypeError("Managed broker project agent cannot change");
            }
            const loaded = await load(input.signal);
            const selected = select(input.definition, loaded.skills);
            definition = structuredClone(input.definition);
            return {
                agent: structuredClone(input.definition),
                skillSelectorPolicy: selected.policy,
                ...(options.environmentContext ? { environmentContext: options.environmentContext } : {}),
                ...(loaded.instructions ? { initialProjectInstructions: loaded.instructions } : {}),
                ...(selected.definitions.length ? { initialSkills: selected.definitions } : {}),
            };
        },
        async refreshProjectSteering(signal, availableToolNames = []) {
            if (!definition)
                throw new TypeError("Managed broker project state is not prepared");
            const loaded = await load(signal);
            const selected = select(definition, loaded.skills);
            return buildInteractiveVeryfrontCloudRuntimeInstructions({
                agentConfig: definition,
                projectId,
                branchId,
                instructions: loaded.instructions,
                skills: availableToolNames.some(isLoadSkillToolName) ? selected.definitions : [],
                availableToolNames,
                skillLoaderToolName: resolveHostedRuntimeSkillLoaderToolName(availableToolNames),
                environmentContext: options.environmentContext,
            });
        },
        ...(options.latestConversationUserText
            ? {
                latestConversationUserText: async (signal) => {
                    signal.throwIfAborted();
                    return await options.latestConversationUserText(signal);
                },
            }
            : {}),
    };
}
